[CmdletBinding(SupportsShouldProcess)]
param()
$ErrorActionPreference = 'Stop'
$workspace = '/home/sharpninja/github/vice-sharp'
$subject = 'docs/plans/PLAN-NATIVERESTORE-001.md'
$identity = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'review-identity.json') -Raw | ConvertFrom-Json
$historical = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'historical-ledger.json') -Raw | ConvertFrom-Json
$previous = Get-Content -LiteralPath $historical.round6Path -Raw | ConvertFrom-Json
$integrity = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'final-integrity.json') -Raw | ConvertFrom-Json
$script:ReviewFindings = [System.Collections.Generic.List[object]]::new()
function Add-ReviewFinding {
    param([string]$Id,[string]$Status,[string]$Severity,[int]$Line,[string]$Section,[string]$Evidence,[string]$Rationale,[string]$Correction,[string]$File = $subject)
    $old = @($previous.findings | Where-Object id -CEQ $Id)
    $h = @($historical.historical | Where-Object id -CEQ $Id)
    $row = [ordered]@{ id = $Id; status = $Status; severity = $Severity; file = $File; line = $Line; section = $Section; evidence = $Evidence; rationale = $Rationale; correction = $Correction }
    if ($old.Count) { $row.round6Status = $old[0].status }
    if ($h.Count) {
        $row.round3bStatus = $h[0].round3bStatus
        $row.round3bDispositionInRevision4 = $h[0].revision4Disposition
        $row.historicalDispositionSource = 'historical-ledger.json, parsed from actual round-3b and round-4 receipts; historical metadata only'
    }
    $script:ReviewFindings.Add([pscustomobject]$row)
}
