    [ordered]@{ criterion = 'Request inside a stolen-cycle run'; outcome = 'Armed gate composition preserves one gate/permit per advanced cycle and withheld permits stop advancement. Actual write clock remains distinct; no forced 100000 value. N15 PASS.' },
