    workClass = 1; subjectRevision = 7; subjectPath = $subject; subjectSha256 = (Get-FileHash -LiteralPath (Join-Path $workspace $subject)).Hash
    checkout = [ordered]@{ branch = $integrity.finalBranch; commit = $integrity.finalHead; nativeCommit = $integrity.finalNativeHead; note = 'Checkout commit is live Git metadata; input-pins.json does not contain it.' }
